import pyomo.environ as pyo

DATA = {
    "availability": [2, 3, 1],
    "demand": [100, 150],
    "capabilities": [[50, 70], [60, 80], [70, 90]],
    "costs": [[100, 200], [150, 250], [200, 300]],
}


def build_model(data=None):
    d = data or DATA

    n_aircraft = len(d["availability"])
    n_routes = len(d["demand"])

    model = pyo.ConcreteModel()

    # Sets
    model.A = pyo.RangeSet(0, n_aircraft - 1)   # aircraft types
    model.R = pyo.RangeSet(0, n_routes - 1)     # routes

    # Variables: number of aircraft of type i assigned to route j
    def assign_bounds(m, i, j):
        return (0, d["availability"][i])

    model.assign = pyo.Var(
        model.A, model.R,
        domain=pyo.NonNegativeIntegers,
        bounds=assign_bounds,
    )

    # Objective: minimize total assignment cost
    def obj_rule(m):
        return sum(
            d["costs"][i][j] * m.assign[i, j]
            for i in m.A for j in m.R
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint 1: availability of each aircraft type not exceeded
    def availability_rule(m, i):
        return sum(m.assign[i, j] for j in m.R) <= d["availability"][i]

    model.availability_con = pyo.Constraint(model.A, rule=availability_rule)

    # Constraint 2: demand of each route satisfied by delivered capacity
    def demand_rule(m, j):
        return sum(
            d["capabilities"][i][j] * m.assign[i, j]
            for i in m.A
        ) >= d["demand"][j]

    model.demand_con = pyo.Constraint(model.R, rule=demand_rule)

    return model


